# Let me also check if the doc has suggested changes / suggestions view
gws docs documents get --params '{"documentId": "1hI2jK3lM4nO5pQ6rS7tU8vW9xY0zA1bC2dE3fG4hI5j", "suggestionsViewMode": "SUGGESTIONS_INLINE"}' --format json 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
print('Top-level keys:', list(data.keys()))
for elem in data.get('body', {}).get('content', []):
    if 'paragraph' in elem:
        for el in elem['paragraph'].get('elements', []):
            tr = el.get('textRun', {})
            content = tr.get('content', '')
            style = tr.get('textStyle', {})
            sugg = {k: v for k, v in style.items() if 'suggestion' in k.lower() or 'suggest' in k.lower()}
            if sugg:
                print(f'Suggestion style found: {sugg} on text: {content[:80]}')
" 2>&1

